CREATE DATABASE TawseelaDb;
GO
USE TawseelaDb;
GO
CREATE TABLE Users(Id INT IDENTITY PRIMARY KEY,UserName NVARCHAR(100) NOT NULL UNIQUE,DisplayName NVARCHAR(200) NOT NULL,PasswordHash NVARCHAR(500) NOT NULL,Role INT NOT NULL,IsActive BIT NOT NULL,MustChangePassword BIT NOT NULL,CreatedAt DATETIME2 NOT NULL);
CREATE TABLE Customers(Id INT IDENTITY PRIMARY KEY,Name NVARCHAR(200) NOT NULL,Phone NVARCHAR(30) NOT NULL,DefaultAddress NVARCHAR(500) NOT NULL,Notes NVARCHAR(1000) NOT NULL,CreatedAt DATETIME2 NOT NULL);
CREATE INDEX IX_Customers_Phone ON Customers(Phone);
CREATE TABLE DeliveryMen(Id INT IDENTITY PRIMARY KEY,Name NVARCHAR(200) NOT NULL,Phone NVARCHAR(30) NOT NULL,Address NVARCHAR(500) NOT NULL,StartDate DATETIME2 NOT NULL,IsActive BIT NOT NULL,CommissionType INT NOT NULL,CommissionValue DECIMAL(18,2) NOT NULL,Notes NVARCHAR(1000) NOT NULL);
CREATE INDEX IX_DeliveryMen_Phone ON DeliveryMen(Phone);
CREATE TABLE Orders(Id INT IDENTITY PRIMARY KEY,OrderNumber NVARCHAR(100) NOT NULL UNIQUE,CreatedAt DATETIME2 NOT NULL,UpdatedAt DATETIME2 NOT NULL,CustomerId INT NOT NULL,PhoneSnapshot NVARCHAR(30) NOT NULL,Address NVARCHAR(500) NOT NULL,Type INT NOT NULL,OrderValue DECIMAL(18,2) NOT NULL,DeliveryFee DECIMAL(18,2) NOT NULL,DeliveryManId INT NULL,Status INT NOT NULL,CollectedAmount DECIMAL(18,2) NOT NULL,Notes NVARCHAR(1000) NOT NULL,CONSTRAINT FK_Orders_Customers FOREIGN KEY(CustomerId) REFERENCES Customers(Id),CONSTRAINT FK_Orders_DeliveryMen FOREIGN KEY(DeliveryManId) REFERENCES DeliveryMen(Id) ON DELETE SET NULL);
CREATE INDEX IX_Orders_CreatedAt_Status_DeliveryManId ON Orders(CreatedAt,Status,DeliveryManId);
CREATE TABLE OrderStatusHistory(Id INT IDENTITY PRIMARY KEY,OrderId INT NOT NULL,Status INT NOT NULL,ChangedAt DATETIME2 NOT NULL,ChangedByUserId INT NULL,Note NVARCHAR(1000) NOT NULL,CONSTRAINT FK_OrderHistory_Order FOREIGN KEY(OrderId) REFERENCES Orders(Id) ON DELETE CASCADE);
CREATE TABLE Expenses(Id INT IDENTITY PRIMARY KEY,Date DATETIME2 NOT NULL,Type NVARCHAR(100) NOT NULL,Amount DECIMAL(18,2) NOT NULL,DeliveryManId INT NULL,Description NVARCHAR(1000) NOT NULL,CreatedByUserId INT NOT NULL,Approved BIT NOT NULL);
CREATE TABLE Settlements(Id INT IDENTITY PRIMARY KEY,Date DATETIME2 NOT NULL,DeliveryManId INT NOT NULL,OrdersValue DECIMAL(18,2) NOT NULL,DeliveryFees DECIMAL(18,2) NOT NULL,AmountCollected DECIMAL(18,2) NOT NULL,Commission DECIMAL(18,2) NOT NULL,ApprovedExpenses DECIMAL(18,2) NOT NULL,AmountDueToOffice DECIMAL(18,2) NOT NULL,AmountPaid DECIMAL(18,2) NOT NULL,Remaining DECIMAL(18,2) NOT NULL,IsClosed BIT NOT NULL,Notes NVARCHAR(1000) NOT NULL,CreatedAt DATETIME2 NOT NULL,CONSTRAINT UQ_Settlement_Driver_Date UNIQUE(DeliveryManId,Date));
CREATE TABLE SettlementDetails(Id INT IDENTITY PRIMARY KEY,SettlementId INT NOT NULL,OrderId INT NOT NULL,CollectedAmount DECIMAL(18,2) NOT NULL,CONSTRAINT UQ_SettlementDetail UNIQUE(SettlementId,OrderId));
CREATE TABLE AuditLogs(Id BIGINT IDENTITY PRIMARY KEY,UserId INT NULL,Action NVARCHAR(100) NOT NULL,DateTime DATETIME2 NOT NULL,Entity NVARCHAR(100) NOT NULL,EntityId NVARCHAR(100) NOT NULL,Description NVARCHAR(2000) NOT NULL);
CREATE TABLE Settings(Id INT IDENTITY PRIMARY KEY,[Key] NVARCHAR(200) NOT NULL UNIQUE,[Value] NVARCHAR(MAX) NOT NULL);
CREATE TABLE Invoices(Id INT IDENTITY PRIMARY KEY,InvoiceNumber NVARCHAR(100) NOT NULL UNIQUE,OrderId INT NOT NULL UNIQUE,CustomerName NVARCHAR(200) NOT NULL,CustomerPhone NVARCHAR(30) NOT NULL,CustomerAddress NVARCHAR(500) NOT NULL,Date DATETIME2 NOT NULL,OrderType INT NOT NULL,OrderValue DECIMAL(18,2) NOT NULL,DeliveryFee DECIMAL(18,2) NOT NULL,Total DECIMAL(18,2) NOT NULL,OrderStatus INT NOT NULL,DeliveryManName NVARCHAR(200) NOT NULL,CollectedAmount DECIMAL(18,2) NOT NULL,IsCollected BIT NOT NULL,Notes NVARCHAR(1000) NOT NULL,CONSTRAINT FK_Invoices_Orders FOREIGN KEY(OrderId) REFERENCES Orders(Id) ON DELETE CASCADE);
